void FMJSpecMarshal::ToMJSpec(const FMJSiteSpec& In, mjsSite* Dst, bool bIsDegrees)
{
	if (!Dst) { return; }
	if (In.bOverride_FromTo)
	{
		if (In.bUseFromTo)
		{
			FMJUnitConverter::UEPositionToMJ(In.From, Dst->fromto);
			FMJUnitConverter::UEPositionToMJ(In.To, Dst->fromto + 3);
		}
		else
		{
			for (int32 i = 0; i < 6; ++i) { Dst->fromto[i] = std::numeric_limits<double>::quiet_NaN(); }
		}
	}
	if (In.bOverride_Size)
	{
		const int32 Count = FMath::Min(In.Size.Num(), 3);
		for (int32 i = 0; i < Count; ++i)
		{
			Dst->size[i] = static_cast<double>(FMJUnitConverter::CmToM(static_cast<double>(In.Size[i])));
		}
	}
	if (In.bOverride_Type)
	{
		Dst->type = ToMJ(In.Type);
	}
	if (In.bOverride_Group)
	{
		Dst->group = static_cast<int>(In.Group);
	}
	if (In.bOverride_Rgba)
	{
		Dst->rgba[0] = In.Rgba.R; Dst->rgba[1] = In.Rgba.G; Dst->rgba[2] = In.Rgba.B; Dst->rgba[3] = In.Rgba.A;
	}
}

void FMJSpecMarshal::FromMJSpec(const mjsSite* Src, FMJSiteSpec& Out, const mjsSite* DefaultSrc, bool bIsDegrees)
{
	if (!Src) { return; }
	mjsSite FallbackDefault = {};
	if (!DefaultSrc)
	{
		mjs_defaultSite(&FallbackDefault);
		DefaultSrc = &FallbackDefault;
	}
	const bool bSrcFromTo = !std::isnan(Src->fromto[0]);
	const bool bDefFromTo = !std::isnan(DefaultSrc->fromto[0]);
	Out.bUseFromTo = bSrcFromTo;
	Out.bOverride_FromTo = (bSrcFromTo != bDefFromTo) || (bSrcFromTo && ArraysDiffer(Src->fromto, DefaultSrc->fromto, 6));
	if (bSrcFromTo)
	{
		FMJUnitConverter::MJPositionToUE(Src->fromto, Out.From);
		FMJUnitConverter::MJPositionToUE(Src->fromto + 3, Out.To);
	}
	Out.bOverride_Size = ArraysDiffer(Src->size, DefaultSrc->size, 3);
	Out.Size.SetNum(3);
	for (int32 i = 0; i < 3; ++i)
	{
		Out.Size[i] = static_cast<double>(FMJUnitConverter::MToCm(static_cast<double>(Src->size[i])));
	}
	Out.bOverride_Type = (Src->type != DefaultSrc->type);
	Out.Type = FromMJ(Src->type);
	Out.bOverride_Group = !FMath::IsNearlyEqual(static_cast<double>(Src->group), static_cast<double>(DefaultSrc->group), 1e-9);
	Out.Group = static_cast<int32>(Src->group);
	Out.bOverride_Rgba = ArraysDiffer(Src->rgba, DefaultSrc->rgba, 4);
	Out.Rgba = FLinearColor(Src->rgba[0], Src->rgba[1], Src->rgba[2], Src->rgba[3]);
}

